pub fn parse_intent_scopes(text: String) -> Option<Rc<IntentScopes>> {
    {
        let lines = Rc::new(text.clone().split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
let schema = field_at(lines.clone(), 0);
if (schema.clone() == "".to_string()) {
            std::option::Option::None
        } else {
            {
                let start = Rc::new(IntentScopeScan::ScanningScopes {
    scopes: Rc::new(vec![]),
});
let scan = Rc::new(v1_rt::list_skip(&lines.clone(), 1)).iter().cloned().fold(start.clone(), |acc: Rc<IntentScopeScan>, l: String| match (*acc.clone()).clone() {
    IntentScopeScan::ScopesEnded { scopes: _, .. } => acc.clone(),
    IntentScopeScan::ScopeLineRefused => acc.clone(),
    IntentScopeScan::ScanningScopes { scopes: xs, .. } => if v1_rt::starts_with(l.clone(), intent_scope_line_prefix()) {
                    match parse_authorization_scope_wire(v1_rt::substring(&l, v1_rt::string_length(&intent_scope_line_prefix()), v1_rt::string_length(&l))) {
    Some(sc) => Rc::new(IntentScopeScan::ScanningScopes {
    scopes: v1_rt::concat(xs.clone(), Rc::new(vec![sc.clone()])),
}),
    std::option::Option::None => Rc::new(IntentScopeScan::ScopeLineRefused),
}
                } else {
                    Rc::new(IntentScopeScan::ScopesEnded {
    scopes: xs.clone(),
})
                },
});
match (*scan.clone()).clone() {
    IntentScopeScan::ScopeLineRefused => std::option::Option::None,
    IntentScopeScan::ScanningScopes { scopes: xs, .. } => if crate::std_algebra::is_empty(xs.clone()) {
                    std::option::Option::None
                } else {
                    Some(Rc::new(IntentScopes {
    schema: schema.clone(),
    scopes: xs.clone(),
}))
                },
    IntentScopeScan::ScopesEnded { scopes: xs, .. } => if crate::std_algebra::is_empty(xs.clone()) {
                    std::option::Option::None
                } else {
                    Some(Rc::new(IntentScopes {
    schema: schema.clone(),
    scopes: xs.clone(),
}))
                },
}
}
        }
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum IntentScopeScan {
    ScanningScopes {
        scopes: Rc<Vec<Rc<AuthorizationScope>>>,
    },
    ScopesEnded {
        scopes: Rc<Vec<Rc<AuthorizationScope>>>,
    },
    ScopeLineRefused,
}
impl IntentScopeScan {
    pub fn scopes(&self) -> Rc<Vec<Rc<AuthorizationScope>>> {
        match self {
            IntentScopeScan::ScanningScopes { scopes: __val, .. } => __val.clone(),
            IntentScopeScan::ScopesEnded { scopes: __val, .. } => __val.clone(),
            IntentScopeScan::ScopeLineRefused => panic!("no scopes on unit variant"),
        }
    }
}

pub fn authorization_scopes_render(scopes: Rc<Vec<Rc<AuthorizationScope>>>) -> String {
    if crate::std_algebra::is_empty(scopes.clone()) {
        "no scopes".to_string()
    } else {
        scopes.iter().cloned().fold("".to_string(), |acc: String, s: Rc<AuthorizationScope>| if (acc.clone() == "".to_string()) {
            authorization_scope_render(s.clone())
        } else {
            v1_rt::concat(acc.clone(), v1_rt::concat(" + ".to_string(), authorization_scope_render(s.clone())))
        })
    }
}

pub fn authorization_scope_render(scope: Rc<AuthorizationScope>) -> String {
    v1_rt::concat(crate::std_effect_grant::effect_verb_label(scope.verb.clone()), v1_rt::concat(" ".to_string(), v1_rt::concat(scope.action.clone(), v1_rt::concat(" on ".to_string(), crate::std_effect_grant::namespace_position_label(scope.resource.clone())))))
}

pub fn authorization_refusal_reason(cause: Rc<AuthorizationRefusalCause>) -> String {
    match (*cause.clone()).clone() {
    AuthorizationRefusalCause::AuthorizationNotGranted { escalation_id: id, .. } => v1_rt::concat("operator authorization absent for escalation ".to_string(), id.clone()),
    AuthorizationRefusalCause::AuthorizationExpired { expires_at: exp, observed_at: at, .. } => v1_rt::concat("operator authorization expired at ".to_string(), v1_rt::concat(exp.clone(), v1_rt::concat(", observed at ".to_string(), at.clone()))),
    AuthorizationRefusalCause::AuthorizationObservedBeforeGrant { granted_at: g, observed_at: at, .. } => v1_rt::concat("operator authorization granted at ".to_string(), v1_rt::concat(g.clone(), v1_rt::concat(" is observed at the earlier instant ".to_string(), v1_rt::concat(at.clone(), "; the clock is behind the decision or the instant is stale".to_string())))),
    AuthorizationRefusalCause::AuthorizationAlreadyCompleted { completed_by: who, completed_at: when, .. } => v1_rt::concat("operator authorization already completed by attempt ".to_string(), v1_rt::concat(who.clone(), v1_rt::concat(" at ".to_string(), when.clone()))),
    AuthorizationRefusalCause::AuthorizationClaimedByOtherAttempt { requested: req, holder, .. } => v1_rt::concat("operator authorization is claimed by another attempt: requested ".to_string(), v1_rt::concat(req.clone(), v1_rt::concat(", held by ".to_string(), holder.clone()))),
    AuthorizationRefusalCause::AuthorizationAborted { aborted_by: who, cause: why, .. } => v1_rt::concat("operator authorization aborted by attempt ".to_string(), v1_rt::concat(who.clone(), v1_rt::concat(": ".to_string(), why.clone()))),
    AuthorizationRefusalCause::AuthorizationEscalationMismatch { requested: req, granted: got, .. } => v1_rt::concat("operator authorization escalation mismatch: requested ".to_string(), v1_rt::concat(req.clone(), v1_rt::concat(", granted ".to_string(), got.clone()))),
    AuthorizationRefusalCause::AuthorizationScopeNotGranted { required: missing, granted: got, .. } => v1_rt::concat("operator authorization does not cover a required capability: ".to_string(), v1_rt::concat(authorization_scope_render(missing.clone()), v1_rt::concat("; granted ".to_string(), authorization_scopes_render(got.clone())))),
    AuthorizationRefusalCause::AuthorizationScopesUnstated { escalation_id: id, .. } => v1_rt::concat("operator authorization request states no scopes for escalation ".to_string(), id.clone()),
    AuthorizationRefusalCause::AuthorizationAttemptMismatch { requested: req, granted: got, .. } => v1_rt::concat("operator authorization issued for a different attempt: requested ".to_string(), v1_rt::concat(req.clone(), v1_rt::concat(", granted ".to_string(), got.clone()))),
    AuthorizationRefusalCause::AuthorizationIntentMismatch { requested: req, granted: got, .. } => v1_rt::concat("operator authorization issued for a different planned action: requested intent ".to_string(), v1_rt::concat(crate::std_content_hash::serialize_content_hash(req.clone()), v1_rt::concat(", granted intent ".to_string(), crate::std_content_hash::serialize_content_hash(got.clone())))),
    AuthorizationRefusalCause::AuthorizationIntentIncomparable { requested: req, granted: got, .. } => v1_rt::concat("operator authorization intent hash is cross-family incomparable: requested ".to_string(), v1_rt::concat(crate::std_content_hash::serialize_content_hash(req.clone()), v1_rt::concat(", granted ".to_string(), crate::std_content_hash::serialize_content_hash(got.clone())))),
    AuthorizationRefusalCause::AuthorizationDeniedByOperator { escalation_id: id, denied_by: who, denied_at: when, reason: why, .. } => v1_rt::concat("operator DENIED escalation ".to_string(), v1_rt::concat(id.clone(), v1_rt::concat(" at ".to_string(), v1_rt::concat(when.clone(), v1_rt::concat(" by ".to_string(), v1_rt::concat(who.clone(), v1_rt::concat(": ".to_string(), why.clone()))))))),
}
}
